using System;using System.IO;using System.Net;using System.Text;using System.Web.Script.Serialization;
class GitHubRelease {
 static string Read(WebResponse response){using(var stream=response.GetResponseStream())using(var reader=new StreamReader(stream,Encoding.UTF8)){var text=new StringBuilder();char[] buffer=new char[4096];int n;while((n=reader.Read(buffer,0,buffer.Length))>0){text.Append(buffer,0,n);if(text.Length>1048576)throw new Exception("Release response exceeds limit");}return text.ToString();}}
 static void Output(HttpWebResponse response){using(response){var json=new JavaScriptSerializer();json.MaxJsonLength=2200000;Console.Write(json.Serialize(new {status=(int)response.StatusCode,body=Read(response)}));}}
 static int Main(){try{ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create("https://api.github.com/repos/finnwang6-droid/AssetNest/releases/latest");request.Timeout=10000;request.ReadWriteTimeout=10000;request.AllowAutoRedirect=false;request.AutomaticDecompression=DecompressionMethods.GZip|DecompressionMethods.Deflate;request.Accept="application/vnd.github+json";request.UserAgent="AssetNest-Update-Check";request.Headers.Add("X-GitHub-Api-Version","2022-11-28");try{Output((HttpWebResponse)request.GetResponse());}catch(WebException e){if(e.Response==null)throw;Output((HttpWebResponse)e.Response);}return 0;}catch{Console.Error.Write("Cannot connect to GitHub Releases");return 1;}}
}
